export function createSearch(fetchUsers) {
  const state = { draft: '', submitted: '', status: 'idle', items: [], error: null };
  let latestRequest = 0;
  let disposed = false;

  async function runSearch(query) {
    if (disposed || query === '') return;

    // Identity belongs to the attempt, including repeated identical queries.
    const request = ++latestRequest;
    state.submitted = query;
    state.status = 'loading';
    state.error = null;

    try {
      const users = await fetchUsers(query);
      if (disposed || request !== latestRequest) return;

      state.items = users.map(user => ({ id: user.user_id, label: user.display_name }));
      state.status = 'success';
    } catch (error) {
      if (disposed || request !== latestRequest) return;

      state.error = error instanceof Error ? error.message : String(error);
      state.status = 'error';
    }
  }

  return {
    setDraft(value) {
      if (!disposed) state.draft = value;
    },
    submit() { return runSearch(state.draft.trim()); },
    retry() { return runSearch(state.submitted); },
    getState() { return structuredClone(state); },
    dispose() { disposed = true; },
  };
}

